using Azure.Storage.Blobs;
using Azure.Storage.Blobs.Models;

/// <summary>
/// Validation class for inbound container
/// </summary>
class OMGAzureValidator_InboundContainer extends OMGAzureValidator
{            
}

Method.Source:
/// <summary>
/// Validates the Azure components of inbound from azure container
/// </summary>
/// <returns>True if all ok</returns>
protected boolean validateSourceContainer()
{
    OMGInboundDataContract_AzureContainer   inboundDataContract = this.parmDataContract();
    BlobContainerClient                     blobContainerClient;        
    boolean                                 ret             = true;
    ;

    if (!inboundDataContract.parmSourceContainer())
    {
        ret = checkFailed("@OMG:SourceContainerMissing");
    }

    if (ret)
    {
        // We can only check if the container part exists (not the directory part)
        blobContainerClient = blobServiceClient.GetBlobContainerClient(inboundDataContract.parmSourceContainer());                                    

        if (!OMGFeatures::checkBlobContainerExist(blobContainerClient))
        {
            ret = checkFailed(strFmt("@OMG:SourceContainerDoesNotExist", inboundDataContract.parmSourceContainer()));
        }                                    
    }

    return ret;
}

/// <summary>
/// Validates the archiving parameters
/// </summary>
/// <returns>True if all ok</returns>
protected boolean validateArchiving()
{
    OMGInboundDataContract_AzureContainer   inboundDataContract = this.parmDataContract();
    BlobContainerClient                     blobContainerClient;
    boolean                                 ret = true;
    ;

    if (inboundDataContract.parmPostImportAction() == OMGPostImportAction::Archive && !inboundDataContract.parmArchiveContainer())
    {
        ret = checkFailed("@OMG:ArchiveContainerMissing");
    }

    if (ret)
    {
        if (inboundDataContract.parmPostImportAction() == OMGPostImportAction::Archive)
        {
            // We can only check if the container part exists (not the directory part)
            blobContainerClient = blobServiceClient.GetBlobContainerClient(inboundDataContract.parmArchiveContainer());

            if (!OMGFeatures::checkBlobContainerExist(blobContainerClient))
            {
                ret = checkFailed(strFmt("@OMG:ArchiveContainerDoesNotExist", inboundDataContract.parmArchiveContainer()));
            }
        }
    }
    return ret;
}

/// <summary>
/// Calls super and if that is ok, checks the source and archiving
/// </summary>
/// <returns>True if all ok</returns>
public boolean validate()
{
    boolean     ret     = super();
    boolean     sourceOk;
    boolean     archiveOk;
    ;

    if (ret)
    {
        sourceOk   = this.validateSourceContainer();
        archiveOk  = this.validateArchiving();            
    }

    return ret && sourceOk && archiveOk;
}
